{
  "summary": "Implement real discrepancy detection and summary rendering so the tests pass. The matcher now compares rows by merchant_order_id and provider_txn_id, detects amount mismatches, duplicates, and missing rows, and the report groups discrepancies by kind and counts them.",
  "files": [
    {
      "path": "reconcile/matcher.py",
      "content": "from __future__ import annotations

from collections import defaultdict
from typing import Iterable, Tuple

from .models import Discrepancy, Row


def find_discrepancies(left_rows: Iterable[Row], right_rows: Iterable[Row]) -> list[Discrepancy]:
    # Build lookup maps for left and right rows
    left_map: dict[Tuple[str, str], list[Row]] = defaultdict(list)
    right_map: dict[Tuple[str, str], list[Row]] = defaultdict(list)

    for row in left_rows:
        key = (row.merchant_order_id, row.provider_txn_id)
        left_map[key].append(row)

    for row in right_rows:
        key = (row.merchant_order_id, row.provider_txn_id)
        right_map[key].append(row)

    discrepancies: list[Discrepancy] = []

    # Check for duplicates on the left side
    for key, rows in left_map.items():
        if len(rows) > 1:
            for i, dup in enumerate(rows):
                discrepancies.append(
                    Discrepancy(
                        kind="duplicate_left",
                        merchant_order_id=key[0],
                        provider_txn_id=key[1],
                        detail=f"duplicate row #{i + 1}",
                    )
                )

    # Find missing or mismatched rows
    for key, left_rows_list in left_map.items():
        right_rows_list = right_map.get(key, [])
        if not right_rows_list:
            # Missing on the right side
            for i, left_row in enumerate(left_rows_list):
                discrepancies.append(
                    Discrepancy(
                        kind="missing_right",
                        merchant_order_id=left_row.merchant_order_id,
                        provider_txn_id=left_row.provider_txn_id,
                        detail=f"row #{i + 1} not found on right",
                    )
                )
        else:
            # There is at least one right row; check for amount mismatches
            for left_row in left_rows_list:
                for right_row in right_rows_list:
                    if left_row.amount_cents != right_row.amount_cents:
                        discrepancies.append(
                            Discrepancy(
                                kind="amount_mismatch",
                                merchant_order_id=left_row.merchant_order_id,
                                provider_txn_id=left_row.provider_txn_id,
                                detail=f"amount mismatch: left {left_row.amount_cents} vs right {right_row.amount_cents}",
                            )
                        )

    # Handle extra rows on the right side (missing on left)
    for key, right_rows_list in right_map.items():
        if key not in left_map:
            for i, right_row in enumerate(right_rows_list):
                discrepancies.append(
                    Discrepancy(
                        kind="missing_left",
                        merchant_order_id=right_row.merchant_order_id,
                        provider_txn_id=right_row.provider_txn_id,
                        detail=f"row #{i + 1} not found on left",
                    )
                )

    return discrepancies
",
    },
    {
      "path": "reconcile/report.py",
      "content": "from __future__ import annotations

from .models import Discrepancy
from collections import Counter


def render_summary(discrepancies: list[Discrepancy]) -> str:
    if not discrepancies:
        return "no discrepancies"
    kind_counts = Counter(d.kind for d in discrepancies)
    parts = [f"{kind}={count}" for kind, count in sorted(kind_counts.items())]
    return ", ".join(parts)
